def verify_pointer_operands(code, expected, data_sites=()):
    """Validate raw fields independently of the loaded-target comparison."""
    if not set(data_sites).issubset(expected):
        raise ValueError('Unbound assembly DATA pointer metadata')
    for offset, target in expected.items():
        base = 0x80000 if offset in data_sites else 0x10000
        if (offset < 0 or offset + 4 > len(code)
                or int.from_bytes(code[offset:offset+4], 'little') + base != target):
            raise ValueError('Assembly pointer operand differs')


def require_disjoint(ranges):
    ordered = sorted(ranges)
    if any(start < 0 or end <= start for start, end in ordered):
        raise ValueError('Invalid code range')
    if any(left[1] > right[0] for left, right in zip(ordered, ordered[1:])):
        raise ValueError('Overlapping source coverage')


def c_coverage_ranges(inventory):
    return [(int(row['raw_offset'], 16), int(row['raw_offset'], 16)+row['bytes'])
            for row in inventory['spans']+inventory.get('non_routine_code_spans', [])]


def verify(exe, directory, c_inventory):
    if hashlib.sha256(exe).hexdigest() != TARGET_SHA256:
        raise ValueError('Unknown FATE.EXE')
    if c_inventory['target_sha256'] != TARGET_SHA256:
        raise ValueError('C inventory target differs')
    ranges = c_coverage_ranges(c_inventory)
    pointers = read_le_fixups(exe)['pointers']
    rows, constants = [], []
    non_routines = {unit[0] for unit in NON_ROUTINE_UNITS}
    for symbol, source, filename, address, size, expected in ROUTINES+NON_ROUTINE_UNITS:
        code = (directory/filename).read_bytes()
        if symbol in GROUP_SLICES:
            start, total = GROUP_SLICES[symbol]
            if len(code) != total:
                raise ValueError('Assembly group size differs: '+filename)
            code = code[start:start+size]
        entry = PUBLIC_ENTRIES.get(symbol, address)
        if not address <= entry < address+size:
            raise ValueError('Public entry outside verified extent: '+symbol)
        raw = address+0x25600
        if len(code) != size or code != exe[raw:raw+size]:
            raise ValueError(code_mismatch(symbol, code, exe[raw:raw+size], address))
        actual = pointer_range(pointers, address, size)
        if actual != expected:
            raise ValueError('Assembly LE pointers differ: '+symbol+'; '
                             + relocation_mismatch(actual, expected))
        verify_pointer_operands(code, expected, DATA_POINTER_SITES.get(symbol, ()))
        ranges.append((raw, raw+size))
        row = dict(symbol=symbol, source='src/'+source, binary=filename,
                         sha256=hashlib.sha256(code).hexdigest(), bytes=size,
                         raw_offset=hex(raw), loaded_address=hex(address),
                         public_entry=hex(entry),
                         binary_offset=GROUP_SLICES.get(symbol, (0,))[0],
                         le_pointers=len(expected))
        if symbol in non_routines:
            row.pop('public_entry')
            row['kind'] = NON_ROUTINE_KINDS.get(symbol, 'declared read-only tables in CODE')
            constants.append(row)
        else:
            rows.append(row)
    require_disjoint(ranges)
    return dict(target_sha256=TARGET_SHA256, routines=len(rows),
                unique_code_bytes=sum(row['bytes'] for row in rows+constants),
                le_pointers=sum(row['le_pointers'] for row in rows+constants),
                non_routine_code_spans=constants,
                format='NASM flat binaries', final_linked_placement_verified=False,
                c_inventory_used_only_for_overlap_check=True, spans=rows)


if __name__ == '__main__':
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('executable', type=Path)
    parser.add_argument('directory', type=Path)
    parser.add_argument('c_inventory', type=Path)
    parser.add_argument('--output', type=Path, required=True)
    args = parser.parse_args()
    result = verify(args.executable.read_bytes(), args.directory,
                    json.loads(args.c_inventory.read_text(encoding='utf-8')))
    args.output.write_text(json.dumps(result, indent=2)+'\n', encoding='utf-8')
    print(f"PASS: {result['routines']} assembly routines, {result['unique_code_bytes']} bytes, "
          f"{result['le_pointers']} LE pointers; no overlap with C inventory")
